-- Deathknell (map 751, zone 4933) class quests 24964-24969 could never be completed.
--
-- Each quest counts kill credit 44175 when the player hits a Training Dummy (4144794) with their class spell, or
-- heals a Wounded Deathguard (4144795) with Flash Heal. The SmartAI spell-hit events came from Cata, which has no
-- spell ranks, and name rank 1 (Charge 100, Arcane Missiles 5143, ...). SMART_EVENT_SPELLHIT matches the exact spell
-- id, and these quests start at level 128, where a character casts its top rank (up to rank 27 here), so no hit
-- ever counted. Now one event per rank of each spell (spell_ranks as of 2026-11-24): the n-th spell of a creature
-- uses ids n * 100 + rank.
--
-- The dummies keep flags_extra CANNOT_ENTER_COMBAT: they never fight back or chase (BFA-HavenCore #727 fixed a
-- chasing dummy, which does not happen here).
DELETE FROM `smart_scripts` WHERE `entryorguid` = 4144794 AND `source_type` = 0;

DELETE FROM `smart_scripts` WHERE `entryorguid` = 4144795 AND `source_type` = 0;
